export enum AppState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  ANALYZED = 'ANALYZED',
  STRATEGIZING = 'STRATEGIZING',
  STRATEGIZED = 'STRATEGIZED',
  DIVERGING = 'DIVERGING',
  DIVERGED = 'DIVERGED',
  EVALUATING = 'EVALUATING',
  EVALUATED = 'EVALUATED',
  RANKING = 'RANKING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export interface AnalysisData {
  subject_state: string;
  scene_conflict: string;
  hidden_details: string;
}

export interface EvaluationResult {
  candidate: string;
  scores: {
    novelty: number;
    empathy: number;
    brevity: number;
    distance: number;
    intelligence: number;
    incongruity: number;
  };
  reason: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisData, EvaluationResult } from "../types";

const MODEL_FAST = 'gemini-3-flash-preview'; 
const MODEL_DEEP = 'gemini-3-pro-preview';

// --- Prompts (Same as before, simplified for modularity) ---
const AGENT_A_SYSTEM = `资深图像分析师。精确描述图片事实、潜在违和感。JSON格式。`;
const AGENT_B_SYSTEM = `幽默理论家。基于分析，从[对象类比, 良性违背, 反差讽刺, 叙事外推]选一策略并说明理由。`;
const AGENT_C_SYSTEM = `Z世代大喜利玩家。创作10个短小精悍(15字内)、荒诞、有冲击力的回答。`;
const AGENT_D_SYSTEM = `幽默批评家。对候选回答进行6维度评分(0-4分)：原创、共鸣、简洁、关联、智力、不一致解决。`;
const AGENT_E_SYSTEM = `评审员。选出Top 1，严禁句号。`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const runAnalysis = async (base64: string, mime: string): Promise<AnalysisData> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: MODEL_FAST,
    contents: { parts: [{ inlineData: { mimeType: mime, data: base64 } }, { text: "分析此图" }] },
    config: {
      systemInstruction: AGENT_A_SYSTEM,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          subject_state: { type: Type.STRING },
          scene_conflict: { type: Type.STRING },
          hidden_details: { type: Type.STRING }
        },
        required: ["subject_state", "scene_conflict", "hidden_details"]
      }
    }
  });
  return JSON.parse(response.text);
};

export const runStrategy = async (base64: string, mime: string, analysis: AnalysisData): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: MODEL_FAST,
    contents: { parts: [{ inlineData: { mimeType: mime, data: base64 } }, { text: `分析：${JSON.stringify(analysis)}\n匹配策略。` }] },
    config: { systemInstruction: AGENT_B_SYSTEM }
  });
  return response.text;
};

export const runDivergence = async (base64: string, mime: string, analysis: AnalysisData, strategy: string): Promise<string[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: MODEL_DEEP,
    contents: { parts: [{ inlineData: { mimeType: mime, data: base64 } }, { text: `背景：${JSON.stringify(analysis)}\n策略：${strategy}\n生成10个候选。` }] },
    config: {
      systemInstruction: AGENT_C_SYSTEM,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: { candidates: { type: Type.ARRAY, items: { type: Type.STRING } } }
      }
    }
  });
  return JSON.parse(response.text).candidates;
};

export const runEvaluation = async (base64: string, mime: string, analysis: AnalysisData, candidates: string[]): Promise<EvaluationResult[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: MODEL_DEEP,
    contents: { parts: [{ inlineData: { mimeType: mime, data: base64 } }, { text: `分析：${JSON.stringify(analysis)}\n候选：${JSON.stringify(candidates)}\n执行评分。` }] },
    config: {
      systemInstruction: AGENT_D_SYSTEM,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          evaluations: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                candidate: { type: Type.STRING },
                scores: { 
                  type: Type.OBJECT, 
                  properties: {
                    novelty: { type: Type.NUMBER },
                    empathy: { type: Type.NUMBER },
                    brevity: { type: Type.NUMBER },
                    distance: { type: Type.NUMBER },
                    intelligence: { type: Type.NUMBER },
                    incongruity: { type: Type.NUMBER }
                  }
                },
                reason: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  });
  return JSON.parse(response.text).evaluations;
};

export const runFinalRanking = async (evaluations: EvaluationResult[]): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: MODEL_DEEP,
    contents: `评分：${JSON.stringify(evaluations)}\n选出Top 1内容。`,
    config: { systemInstruction: AGENT_E_SYSTEM }
  });
  return response.text.replace(/[。\.！!？\?~～]+$/, "").trim();
};

import React, { useState, useCallback, useEffect } from 'react';
import * as Gemini from './services/geminiService';
import { Spinner } from './components/Spinner';
import { MemeCanvas } from './components/MemeCanvas';
import { AppState, AnalysisData, EvaluationResult } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState<string>("image/jpeg");
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Persistence of intermediate data
  const [analysis, setAnalysis] = useState<AnalysisData | null>(null);
  const [strategy, setStrategy] = useState<string | null>(null);
  const [candidates, setCandidates] = useState<string[]>([]);
  const [evaluations, setEvaluations] = useState<EvaluationResult[]>([]);
  const [finalCaption, setFinalCaption] = useState<string>("");

  const processFile = (file: File) => {
    setMimeType(file.type);
    const reader = new FileReader();
    reader.onload = (e) => {
      if (e.target?.result) {
        setImageSrc(e.target.result as string);
        resetState();
      }
    };
    reader.readAsDataURL(file);
  };

  const resetState = () => {
    setAppState(AppState.IDLE);
    setAnalysis(null);
    setStrategy(null);
    setCandidates([]);
    setEvaluations([]);
    setFinalCaption("");
    setErrorMessage(null);
  };

  const handleStep1 = async () => {
    if (!imageSrc) return;
    setAppState(AppState.ANALYZING);
    try {
      const b64 = imageSrc.split(',')[1];
      const res = await Gemini.runAnalysis(b64, mimeType);
      setAnalysis(res);
      setAppState(AppState.ANALYZED);
    } catch (e: any) { setErrorMessage(e.message); setAppState(AppState.ERROR); }
  };

  const handleStep2 = async () => {
    if (!imageSrc || !analysis) return;
    setAppState(AppState.STRATEGIZING);
    try {
      const b64 = imageSrc.split(',')[1];
      const res = await Gemini.runStrategy(b64, mimeType, analysis);
      setStrategy(res);
      setAppState(AppState.STRATEGIZED);
    } catch (e: any) { setErrorMessage(e.message); setAppState(AppState.ERROR); }
  };

  const handleStep3 = async () => {
    if (!imageSrc || !analysis || !strategy) return;
    setAppState(AppState.DIVERGING);
    try {
      const b64 = imageSrc.split(',')[1];
      const res = await Gemini.runDivergence(b64, mimeType, analysis, strategy);
      setCandidates(res);
      setAppState(AppState.DIVERGED);
    } catch (e: any) { setErrorMessage(e.message); setAppState(AppState.ERROR); }
  };

  const handleStep4 = async () => {
    if (!imageSrc || !analysis || !candidates.length) return;
    setAppState(AppState.EVALUATING);
    try {
      const b64 = imageSrc.split(',')[1];
      const res = await Gemini.runEvaluation(b64, mimeType, analysis, candidates);
      setEvaluations(res);
      setAppState(AppState.EVALUATED);
    } catch (e: any) { setErrorMessage(e.message); setAppState(AppState.ERROR); }
  };

  const handleStep5 = async () => {
    if (!evaluations.length) return;
    setAppState(AppState.RANKING);
    try {
      const res = await Gemini.runFinalRanking(evaluations);
      setFinalCaption(res);
      setAppState(AppState.SUCCESS);
    } catch (e: any) { setErrorMessage(e.message); setAppState(AppState.ERROR); }
  };

  // Clipboard paste support
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      const file = e.clipboardData?.items[0]?.getAsFile();
      if (file) processFile(file);
    };
    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, []);

  const steps = [
    { key: 'analysis', label: '1. 视觉分析', state: AppState.ANALYZED, loading: AppState.ANALYZING, action: handleStep1, data: analysis },
    { key: 'strategy', label: '2. 幽默建模', state: AppState.STRATEGIZED, loading: AppState.STRATEGIZING, action: handleStep2, data: strategy },
    { key: 'diverge', label: '3. 创意发散', state: AppState.DIVERGED, loading: AppState.DIVERGING, action: handleStep3, data: candidates },
    { key: 'eval', label: '4. 维度评估', state: AppState.EVALUATED, loading: AppState.EVALUATING, action: handleStep4, data: evaluations },
    { key: 'rank', label: '5. 专家最终排序', state: AppState.SUCCESS, loading: AppState.RANKING, action: handleStep5, data: finalCaption }
  ];

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white font-sans selection:bg-yellow-400 selection:text-black">
      <div className="container mx-auto px-4 py-8 max-w-6xl">
        <header className="mb-12 text-center">
          <h1 className="text-6xl font-black text-yellow-400 italic tracking-tighter mb-2">OOGIRI.OS</h1>
          <p className="text-neutral-500 font-mono text-sm uppercase tracking-widest">Multi-Agent Humor Lab</p>
        </header>

        <main className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          {/* Left Side: Pipeline Controls */}
          <div className="lg:col-span-4 space-y-6 order-2 lg:order-1">
            <div className="bg-neutral-900 border border-neutral-800 rounded-2xl p-6 shadow-xl">
              <h2 className="text-xs font-bold text-neutral-500 mb-6 flex items-center gap-2">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                SYSTEM PIPELINE
              </h2>

              <div className="space-y-4">
                {!imageSrc && (
                   <label className="block w-full cursor-pointer group">
                      <div className="border-2 border-dashed border-neutral-700 rounded-xl p-8 text-center group-hover:border-yellow-500 transition-all">
                        <p className="text-neutral-400 group-hover:text-yellow-400">点击或粘贴图片开始</p>
                      </div>
                      <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} />
                   </label>
                )}

                {imageSrc && steps.map((step, idx) => {
                  const isUnlocked = idx === 0 || !!steps[idx-1].data;
                  const isDone = !!step.data;
                  const isLoading = appState === step.loading;

                  return (
                    <div key={step.key} className={`relative flex flex-col gap-2 p-4 rounded-xl border transition-all ${isDone ? 'bg-green-500/10 border-green-500/50' : isUnlocked ? 'bg-neutral-800 border-neutral-700' : 'opacity-30 border-transparent grayscale cursor-not-allowed'}`}>
                       <div className="flex items-center justify-between">
                          <span className={`text-sm font-bold ${isDone ? 'text-green-400' : 'text-neutral-300'}`}>{step.label}</span>
                          {isLoading ? <Spinner /> : isDone ? <span className="text-green-500">✓</span> : isUnlocked && (
                            <button onClick={step.action} className="bg-yellow-400 text-black text-xs font-black px-3 py-1 rounded-md hover:scale-105 active:scale-95 transition-transform">RUN</button>
                          )}
                       </div>

                       {/* Mini Data Preview */}
                       {isDone && (
                         <div className="text-[10px] font-mono text-neutral-500 mt-1 line-clamp-2 overflow-hidden bg-black/40 p-2 rounded">
                            {typeof step.data === 'string' ? step.data : JSON.stringify(step.data)}
                         </div>
                       )}
                    </div>
                  );
                })}

                {imageSrc && (
                   <button onClick={resetState} className="w-full py-3 text-xs text-neutral-500 hover:text-white transition-colors">RESET WORKSPACE</button>
                )}
              </div>
            </div>

            {errorMessage && (
               <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl text-xs text-red-400 font-mono">
                  [ERROR]: {errorMessage}
               </div>
            )}
          </div>

          {/* Right Side: Visual Output */}
          <div className="lg:col-span-8 order-1 lg:order-2">
            {!imageSrc ? (
              <div className="aspect-video bg-neutral-900/50 border border-neutral-800 rounded-3xl flex items-center justify-center border-dashed">
                 <div className="text-center text-neutral-600">
                    <p className="text-4xl mb-4">🖼️</p>
                    <p className="font-mono text-sm">WAITING FOR INPUT_IMAGE...</p>
                 </div>
              </div>
            ) : (
              <div className="flex flex-col items-center">
                 <MemeCanvas imageSrc={imageSrc} caption={finalCaption} />

                 {/* Live Status Overlay (Simulation) */}
                 {appState !== AppState.IDLE && appState !== AppState.SUCCESS && (
                    <div className="mt-6 flex items-center gap-4 bg-yellow-400/10 px-6 py-2 rounded-full border border-yellow-400/30">
                       <span className="w-2 h-2 bg-yellow-400 rounded-full animate-ping"></span>
                       <span className="text-yellow-400 text-xs font-mono uppercase tracking-widest">
                          Current Agent State: {appState}
                       </span>
                    </div>
                 )}
              </div>
            )}
          </div>
        </main>
      </div>
    </div>
  );
};

